function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'ProductOfNumbers' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with ProductOfNumbers() and no arguments.';
  if (operations.length - 1 > 40000) return 'At most 4 * 10^4 calls to add and getProduct.';
  let length = 0;
  let run = 1;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 1 || !Number.isInteger(a[0])) return 'add and getProduct each take one whole number.';
    if (operations[i] === 'add') {
      if (a[0] < 0 || a[0] > 100) return 'add takes a number from 0 to 100.';
      length++;
      run = a[0] === 0 ? 1 : run * a[0];
      if (run > 2147483647) return 'The product of consecutive numbers must fit in a signed 32-bit integer.';
    } else if (operations[i] === 'getProduct') {
      if (a[0] < 1 || a[0] > 40000) return 'k is between 1 and 4 * 10^4.';
      if (a[0] > length) return 'getProduct(k) needs at least k numbers added so far.';
    } else {
      return 'Only add and getProduct can follow the constructor.';
    }
  }
  return null;
}

