class ProductOfNumbers {
  constructor() {
    this.numbers = [];
  }
  add(num) {
    this.numbers.push(num);
  }
  getProduct(k) {
    let product = 1;
    for (let i = this.numbers.length - k; i < this.numbers.length; i++) product *= this.numbers[i];
    return product;
  }
}

