function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const LIMIT = 2147483647;
  const large = size === 'large';
  const calls = large ? 499 : int(1, 14);
  const zeroRate = rand() < 0.2 ? 0 : large ? 0.01 + rand() * 0.08 : 0.1 + rand() * 0.3;
  const bigRate = rand();
  const maxNum = rand() < 0.5 ? 5 : 100;
  const addRate = 0.3 + rand() * 0.5;
  const operations = ['ProductOfNumbers'];
  const args = [[]];
  // length counts all numbers, sinceZero those after the last zero, run is their product.
  let length = 0;
  let sinceZero = 0;
  let run = 1;
  for (let c = 0; c < calls; c++) {
    if (length === 0 || rand() < addRate) {
      let num = rand() < zeroRate ? 0 : rand() < bigRate ? int(2, maxNum) : 1;
      if (num > 1 && run * num > LIMIT) {
        // Keep every zero-free run's product inside 32 bits.
        const cap = Math.min(maxNum, Math.floor(LIMIT / run));
        num = cap >= 2 ? int(2, cap) : rand() < 0.3 ? 0 : 1;
      }
      operations.push('add');
      args.push([num]);
      length++;
      if (num === 0) {
        sinceZero = 0;
        run = 1;
      } else {
        sinceZero++;
        run *= num;
      }
    } else {
      const r = rand();
      let k;
      if (r < 0.3) k = int(1, Math.min(length, 5));
      else if (r < 0.5) k = length;
      else if (r < 0.75 && sinceZero < length) k = Math.max(1, sinceZero + (rand() < 0.5 ? 0 : 1));
      else k = int(1, length);
      operations.push('getProduct');
      args.push([k]);
    }
  }
  return [operations, args];
}
